class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        self._limit_bytes = int(monthly_limit_mib * 1024 * 1024)

        # name -> {"size": int, "month": str, "counted": bool}
        self._files: dict[str, dict] = {}

        # month -> bytes counted toward quota
        self._used: dict[str, int] = {}

    def upload(self, name: str, size_bytes: int, month: str) -> None:
        if size_bytes <= 0:
            raise ValueError("size_bytes must be positive")

        if name in self._files:
            raise ValueError(f"file '{name}' already exists")

        used = self._used.get(month, 0)
        if used + size_bytes > self._limit_bytes:
            raise ValueError("upload would exceed monthly quota")

        self._files[name] = {"size": size_bytes, "month": month, "counted": True}
        self._used[month] = used + size_bytes

    def delete(self, name: str, month: str) -> None:
        if name not in self._files:
            raise ValueError(f"file '{name}' not found")

        info = self._files[name]
        # Deleting refunds quota only if the file was uploaded in a past month
        # and is being deleted in a later month. In the month of upload,
        # no quota is refunded.
        if info["counted"] and info["month"] != month:
            self._used[info["month"]] -= info["size"]

        del self._files[name]

    def used_bytes(self, month: str) -> int:
        return self._used.get(month, 0)
